import{_ as t,o as r,c as o,a2 as a}from"./chunks/framework.DXa1R37q.js";const u=JSON.parse('{"title":"Requirements","description":"","frontmatter":{},"headers":[],"relativePath":"get-started/requirements.md","filePath":"get-started/requirements.md","lastUpdated":1792956156000}'),d={name:"get-started/requirements.md"};function s(i,e,n,c,l,m){return r(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="requirements" tabindex="-1">Requirements <a class="header-anchor" href="#requirements" aria-label="Permalink to &quot;Requirements&quot;">​</a></h1><p>Check these restrictions before a filesystem quick start. Filesystem-backed Memory, Issues, and Design Docs fail closed outside the supported environment.</p><table tabindex="0"><thead><tr><th>Component</th><th>Runtime</th><th>Other requirements</th></tr></thead><tbody><tr><td><code>@neottia/core</code></td><td>Node.js 20 or newer</td><td>Browser bundles are also published.</td></tr><tr><td>Repository Store and filesystem domains</td><td>Node.js 22.16 or newer, or Bun 1.3.13 or newer for direct Repository Store use</td><td>Linux x64 or arm64; C++17 compiler, Python, Make, and Linux headers for native builds.</td></tr><tr><td>MCP servers</td><td>Node.js 22.16 or newer</td><td>The same filesystem requirements as their domain.</td></tr><tr><td>Pi and OpenCode extensions</td><td>Host Node.js runtime</td><td>The same requirements as their domain package.</td></tr><tr><td>Claude Code distribution</td><td>Claude Code with Node.js 22.20 or newer and <code>npx</code> on <code>PATH</code></td><td>Project MCP approval and the same filesystem requirements as each enabled domain package.</td></tr><tr><td>PostgreSQL Memory</td><td>Node.js 22.16 or newer</td><td>PostgreSQL credentials and an explicit organization, project, and scope ownership model.</td></tr><tr><td>Searchable</td><td>Node.js 22.16 or newer</td><td>Repository Store filesystem support; public network access; Ollama only when using <code>web_ask</code>.</td></tr></tbody></table><p>Filesystem domains require a certified local filesystem: ext4, XFS, Btrfs, tmpfs, or overlay on Linux x64 or arm64; APFS on macOS x64 or arm64; NTFS on Windows Server x64; or UFS2 on FreeBSD 14.x x64 with Node.js. The canonical root and control directory must support the platform&#39;s documented publication, durability, identity, and same-volume hard-link guarantees. Network, shared, removable, and uncertified filesystems or runtime tuples fail closed for leased operations. See <a href="/projects/neottia/repository-store">Repository Store</a> for the exact matrix and diagnostics.</p><p>All four capability shards default to <code>enabled: false</code>. Enable only the capabilities you use.</p><p>Pi can ask before rebuilding a stale cache. OpenCode, Claude Code MCP, and generic MCP are non-interactive, so <code>prompt</code> becomes <code>rebuild</code>. An explicit <code>fail</code> remains <code>fail</code>.</p><p>If a native addon fails to install, confirm the Node version, architecture, compiler, Python, Make, headers, filesystem, and kernel support. Do not treat <code>UnsupportedRuntimeError</code> as canonical-data corruption. See <a href="/projects/neottia/repository-store">Repository Store diagnostics</a>.</p>',7)])])}const h=t(d,[["render",s]]);export{u as __pageData,h as default};
